-- Tahap 5: exam APIs and attendance integration; follows core and event schema.
SET LOCAL ROLE sim_guru_owner;
CREATE FUNCTION app.exam_save(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;k text:=p_data->>'entity';d jsonb:=p_data->'data';rid uuid:=coalesce((p_data->>'id')::uuid,gen_random_uuid());tbl text;old jsonb;n jsonb;p app.exam_periods%ROWTYPE;s app.exam_sessions%ROWTYPE;r app.exam_rooms%ROWTYPE;o app.activity_occurrences%ROWTYPE;uid uuid;v numeric;day date;cid uuid;BEGIN
actor:=app.activity_guard(p_session,true);PERFORM auth_private.require_admin();IF length(btrim(coalesce(p_data->>'reason',''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
tbl:=CASE k WHEN 'period' THEN 'exam_periods' WHEN 'session' THEN 'exam_sessions' WHEN 'room' THEN 'exam_rooms' WHEN 'supervisor' THEN 'exam_supervisor_assignments' WHEN 'committee' THEN 'exam_committee_assignments' END;IF tbl IS NULL THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
EXECUTE format('SELECT to_jsonb(t) FROM app.%I t WHERE id=$1 FOR UPDATE',tbl) INTO old USING rid;
IF coalesce((old->>'version')::bigint,0) IS DISTINCT FROM(p_data->>'version')::bigint OR(old IS NOT NULL AND NOT(old->>'active')::boolean) THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;
IF k='period' THEN
SELECT * INTO p FROM app.exam_periods WHERE id=rid;IF old IS NOT NULL AND p.date_start<=app.activity_today() THEN RAISE EXCEPTION 'ACTIVITY_REFERENCED' USING ERRCODE='42501';END IF;
IF(d->>'dateStart')::date<app.activity_today() OR NOT EXISTS(SELECT 1 FROM app.academic_periods WHERE id=(d->>'academicPeriodId')::uuid AND archived_at IS NULL AND(d->>'dateStart')::date>=date_start AND(d->>'dateEnd')::date<=date_end) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
IF EXISTS(SELECT 1 FROM app.exam_sessions WHERE period_id=rid AND active AND date NOT BETWEEN(d->>'dateStart')::date AND(d->>'dateEnd')::date) OR EXISTS(SELECT 1 FROM app.exam_committee_assignments WHERE period_id=rid AND active AND date NOT BETWEEN(d->>'dateStart')::date AND(d->>'dateEnd')::date) OR(old IS NOT NULL AND p.academic_period_id<>(d->>'academicPeriodId')::uuid AND(EXISTS(SELECT 1 FROM app.exam_sessions WHERE period_id=rid) OR EXISTS(SELECT 1 FROM app.exam_committee_assignments WHERE period_id=rid))) THEN RAISE EXCEPTION 'ACTIVITY_REFERENCED' USING ERRCODE='42501';END IF;
INSERT INTO app.exam_periods(id,academic_period_id,name,date_start,date_end,default_committee_jtm) VALUES(rid,(d->>'academicPeriodId')::uuid,btrim(d->>'name'),(d->>'dateStart')::date,(d->>'dateEnd')::date,(d->>'committeeJtm')::numeric) ON CONFLICT(id) DO UPDATE SET academic_period_id=excluded.academic_period_id,name=excluded.name,date_start=excluded.date_start,date_end=excluded.date_end,default_committee_jtm=excluded.default_committee_jtm,version=app.exam_periods.version+1;
ELSIF k='session' THEN
SELECT * INTO p FROM app.exam_periods WHERE id=(d->>'periodId')::uuid AND active;day:=(d->>'date')::date;
IF p.id IS NULL OR day NOT BETWEEN p.date_start AND p.date_end OR day<app.activity_today() OR(old IS NOT NULL AND(old->>'date')::date<=app.activity_today()) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
IF old IS NOT NULL AND EXISTS(SELECT 1 FROM app.exam_rooms WHERE session_id=rid) AND(old->>'period_id')::uuid<>p.id THEN RAISE EXCEPTION 'ACTIVITY_REFERENCED' USING ERRCODE='42501';END IF;
INSERT INTO app.exam_sessions(id,period_id,date,name,time_start,time_end,scheduled_jtm) VALUES(rid,p.id,day,btrim(d->>'name'),(d->>'timeStart')::time,(d->>'timeEnd')::time,(d->>'jtm')::numeric) ON CONFLICT(id) DO UPDATE SET period_id=excluded.period_id,date=excluded.date,name=excluded.name,time_start=excluded.time_start,time_end=excluded.time_end,scheduled_jtm=excluded.scheduled_jtm,version=app.exam_sessions.version+1;
ELSIF k='room' THEN
SELECT * INTO s FROM app.exam_sessions WHERE id=(d->>'sessionId')::uuid AND active;SELECT * INTO p FROM app.exam_periods WHERE id=s.period_id AND active;
IF s.id IS NULL OR p.id IS NULL OR s.date<app.activity_today() OR(old IS NOT NULL AND(old->>'session_id')::uuid<>s.id) OR NOT EXISTS(SELECT 1 FROM app.subjects WHERE id=(d->>'subjectId')::uuid AND archived_at IS NULL) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
IF old IS NOT NULL AND EXISTS(SELECT 1 FROM app.exam_supervisor_assignments WHERE exam_room_id=rid) AND s.date<=app.activity_today() THEN RAISE EXCEPTION 'ACTIVITY_REFERENCED' USING ERRCODE='42501';END IF;
INSERT INTO app.exam_rooms(id,session_id,name,subject_id,total_students) VALUES(rid,s.id,btrim(d->>'name'),(d->>'subjectId')::uuid,(d->>'totalStudents')::int) ON CONFLICT(id) DO UPDATE SET name=excluded.name,subject_id=excluded.subject_id,total_students=excluded.total_students,version=app.exam_rooms.version+1;
DELETE FROM app.exam_room_classes WHERE exam_room_id=rid;FOR cid IN SELECT value::uuid FROM jsonb_array_elements_text(d->'classIds') LOOP IF NOT EXISTS(SELECT 1 FROM app.classes WHERE id=cid AND academic_period_id=p.academic_period_id AND archived_at IS NULL) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;INSERT INTO app.exam_room_classes VALUES(rid,cid);END LOOP;
ELSE
uid:=(d->>'userId')::uuid;IF NOT EXISTS(SELECT 1 FROM app.app_users WHERE id=uid AND role='guru' AND status='active') THEN RAISE EXCEPTION 'SUBSTITUTE_INVALID' USING ERRCODE='22023';END IF;
IF k='supervisor' THEN
SELECT * INTO r FROM app.exam_rooms WHERE id=(d->>'roomId')::uuid AND active;SELECT * INTO s FROM app.exam_sessions WHERE id=r.session_id AND active;SELECT * INTO p FROM app.exam_periods WHERE id=s.period_id AND active;day:=s.date;
IF r.id IS NULL OR s.id IS NULL OR p.id IS NULL OR day<app.activity_today() THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
IF old IS NOT NULL AND(day<=app.activity_today() OR(old->>'exam_room_id')::uuid<>r.id) THEN RAISE EXCEPTION 'ACTIVITY_REFERENCED' USING ERRCODE='42501';END IF;
INSERT INTO app.exam_supervisor_assignments(id,exam_room_id,user_id,override_jtm) VALUES(rid,r.id,uid,(d->>'overrideJtm')::numeric) ON CONFLICT(id) DO UPDATE SET user_id=excluded.user_id,override_jtm=excluded.override_jtm,version=app.exam_supervisor_assignments.version+1;
ELSE
SELECT * INTO p FROM app.exam_periods WHERE id=(d->>'periodId')::uuid AND active;day:=(d->>'date')::date;
IF p.id IS NULL OR day NOT BETWEEN p.date_start AND p.date_end OR day<app.activity_today() OR(old IS NOT NULL AND((old->>'date')::date<=app.activity_today() OR(old->>'period_id')::uuid<>p.id)) THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
INSERT INTO app.exam_committee_assignments(id,period_id,date,user_id,scheduled_jtm,exclusive_time_start,exclusive_time_end) VALUES(rid,p.id,day,uid,coalesce((d->>'jtm')::numeric,p.default_committee_jtm),(d->>'exclusiveStart')::time,(d->>'exclusiveEnd')::time) ON CONFLICT(id) DO UPDATE SET date=excluded.date,user_id=excluded.user_id,scheduled_jtm=excluded.scheduled_jtm,exclusive_time_start=excluded.exclusive_time_start,exclusive_time_end=excluded.exclusive_time_end,version=app.exam_committee_assignments.version+1;
END IF;END IF;
-- Synchronize future assignment snapshots after master edits; historical sources cannot be edited.
PERFORM app.exam_sync();
EXECUTE format('SELECT to_jsonb(t)||jsonb_build_object(''version'',version::text) FROM app.%I t WHERE id=$1',tbl) INTO n USING rid;
UPDATE app.calendar_state SET revision=revision+1 WHERE singleton;PERFORM app.activity_audit('exam-'||k,rid,p_data->>'reason',old,n);RETURN n;END $$;
CREATE FUNCTION app.exam_sync() RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE q record;oid uuid;aid uuid;prev app.activity_occurrences%ROWTYPE;BEGIN
FOR q IN SELECT v.id source_id,'EXAM_SUPERVISOR'::text kind,s.date,p.academic_period_id,v.user_id,coalesce(v.override_jtm,s.scheduled_jtm) jtm,s.time_start,s.time_end,r.subject_id,r.total_students expected_students,jsonb_build_object('teacherName',u.full_name,'className',r.name,'subjectName',sub.name,'sessionName',s.name,'periodName',p.name) snapshot FROM app.exam_supervisor_assignments v JOIN app.exam_rooms r ON r.id=v.exam_room_id JOIN app.exam_sessions s ON s.id=r.session_id JOIN app.exam_periods p ON p.id=s.period_id JOIN app.app_users u ON u.id=v.user_id JOIN app.subjects sub ON sub.id=r.subject_id WHERE v.active AND r.active AND s.active AND p.active
UNION ALL SELECT c.id,'EXAM_COMMITTEE',c.date,p.academic_period_id,c.user_id,c.scheduled_jtm,coalesce(c.exclusive_time_start,'00:00'::time),coalesce(c.exclusive_time_end,'23:59'::time),NULL::uuid,0,jsonb_build_object('teacherName',u.full_name,'periodName',p.name,'sessionName','Panitia') FROM app.exam_committee_assignments c JOIN app.exam_periods p ON p.id=c.period_id JOIN app.app_users u ON u.id=c.user_id WHERE c.active AND p.active LOOP
SELECT * INTO prev FROM app.activity_occurrences WHERE exam_supervisor_id=q.source_id OR exam_committee_id=q.source_id;
IF prev.id IS NULL THEN
INSERT INTO app.activity_occurrences(kind,date,academic_period_id,subject_id,time_start,time_end,scheduled_jtm,expected_students,snapshot,exam_supervisor_id,exam_committee_id) VALUES(q.kind,q.date,q.academic_period_id,q.subject_id,q.time_start,q.time_end,q.jtm,q.expected_students,q.snapshot,CASE WHEN q.kind='EXAM_SUPERVISOR' THEN q.source_id END,CASE WHEN q.kind='EXAM_COMMITTEE' THEN q.source_id END) RETURNING id INTO oid;
INSERT INTO app.activity_assignments(occurrence_id,original_user_id,effective_user_id) VALUES(oid,q.user_id,q.user_id);
ELSIF prev.removed_at IS NULL AND q.date>=app.activity_today() AND(prev.date,prev.time_start,prev.time_end,prev.scheduled_jtm,prev.expected_students,prev.subject_id,prev.snapshot,(SELECT original_user_id FROM app.activity_assignments WHERE occurrence_id=prev.id)) IS DISTINCT FROM(q.date,q.time_start,q.time_end,q.jtm,q.expected_students,q.subject_id,q.snapshot,q.user_id) THEN
IF EXISTS(SELECT 1 FROM app.activity_assignments a JOIN app.activity_confirmations c ON c.assignment_id=a.id AND c.revoked_at IS NULL WHERE a.occurrence_id=prev.id) THEN RAISE EXCEPTION 'ACTIVITY_REFERENCED' USING ERRCODE='42501';END IF;
UPDATE app.activity_occurrences SET date=q.date,time_start=q.time_start,time_end=q.time_end,scheduled_jtm=q.jtm,expected_students=q.expected_students,subject_id=q.subject_id,snapshot=q.snapshot WHERE id=prev.id;
UPDATE app.activity_assignments SET original_user_id=q.user_id,effective_user_id=q.user_id,effective_name=q.snapshot->>'teacherName',version=version+1 WHERE occurrence_id=prev.id;END IF;
END LOOP;
FOR q IN SELECT o.id,a.effective_user_id FROM app.activity_occurrences o JOIN app.activity_assignments a ON a.occurrence_id=o.id WHERE o.kind IN('EXAM_SUPERVISOR','EXAM_COMMITTEE') AND o.removed_at IS NULL AND o.date>=app.activity_today() LOOP PERFORM app.duty_candidate(q.effective_user_id,q.id);END LOOP;END $$;
CREATE FUNCTION app.exam_descendants(p_kind text,p_id uuid) RETURNS SETOF uuid LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT o.id FROM app.activity_occurrences o WHERE o.removed_at IS NULL AND((p_kind='period' AND app.exam_period_for(o.id)=p_id) OR(p_kind='supervisor' AND o.exam_supervisor_id=p_id) OR(p_kind='committee' AND o.exam_committee_id=p_id) OR EXISTS(SELECT 1 FROM app.exam_supervisor_assignments v JOIN app.exam_rooms r ON r.id=v.exam_room_id WHERE v.id=o.exam_supervisor_id AND((p_kind='room' AND r.id=p_id) OR(p_kind='session' AND r.session_id=p_id)))) $$;
CREATE FUNCTION app.exam_delete_fingerprint(p_kind text,p_id uuid) RETURNS text LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE t text;v jsonb;BEGIN t:=CASE p_kind WHEN 'period' THEN 'exam_periods' WHEN 'session' THEN 'exam_sessions' WHEN 'room' THEN 'exam_rooms' WHEN 'supervisor' THEN 'exam_supervisor_assignments' WHEN 'committee' THEN 'exam_committee_assignments' END;IF t IS NULL THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;EXECUTE format('SELECT to_jsonb(t) FROM app.%I t WHERE id=$1 AND active',t) INTO v USING p_id;IF v IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;RETURN md5(jsonb_build_array(v,(SELECT jsonb_agg(app.duty_fingerprint(id) ORDER BY id) FROM app.exam_descendants(p_kind,p_id) id),(SELECT revision FROM app.calendar_state WHERE singleton))::text);END $$;
CREATE FUNCTION app.exam_delete(p_session text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;v ops.module_previews%ROWTYPE;k text;rid uuid;oid uuid;tbl text;BEGIN actor:=app.activity_guard(p_session,true);PERFORM auth_private.require_admin();
IF p_data->>'previewId' IS NULL THEN k:=p_data->>'entity';rid:=(p_data->>'id')::uuid;IF length(btrim(coalesce(p_data->>'reason',''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'ACTIVITY_INVALID' USING ERRCODE='22023';END IF;
FOR oid IN SELECT * FROM app.exam_descendants(k,rid) LOOP PERFORM finance.guard_open((SELECT date FROM app.activity_occurrences WHERE id=oid));END LOOP;
INSERT INTO ops.module_previews(actor_id,request,fingerprint) VALUES(actor,p_data,app.exam_delete_fingerprint(k,rid)) RETURNING * INTO v;
RETURN jsonb_build_object('previewId',v.id,'expiresAt',v.expires_at,'assignments',(SELECT count(*) FROM app.exam_descendants(k,rid)),'baps',(SELECT count(*) FROM app.exam_baps WHERE occurrence_id IN(SELECT * FROM app.exam_descendants(k,rid))),'netJtm',coalesce((SELECT sum(jtm) FROM finance.jtm_ledger WHERE occurrence_id IN(SELECT * FROM app.exam_descendants(k,rid))),0)::text,'sessions',(SELECT count(*) FROM app.exam_sessions WHERE active AND k='period' AND period_id=rid),'rooms',(SELECT count(*) FROM app.exam_rooms r JOIN app.exam_sessions s ON s.id=r.session_id WHERE r.active AND((k='period' AND s.period_id=rid) OR(k='session' AND s.id=rid))));END IF;
SELECT * INTO v FROM ops.module_previews WHERE id=(p_data->>'previewId')::uuid FOR UPDATE;k:=v.request->>'entity';rid:=(v.request->>'id')::uuid;
IF v.id IS NULL OR v.actor_id<>actor OR v.consumed_at IS NOT NULL OR v.expires_at<=clock_timestamp() OR p_data->>'confirmed' IS DISTINCT FROM 'true' OR v.fingerprint IS DISTINCT FROM app.exam_delete_fingerprint(k,rid) THEN RAISE EXCEPTION 'PREVIEW_STALE' USING ERRCODE='40001';END IF;
FOR oid IN SELECT * FROM app.exam_descendants(k,rid) LOOP PERFORM finance.guard_open((SELECT date FROM app.activity_occurrences WHERE id=oid));PERFORM app.duty_cleanup(oid,actor);UPDATE app.activity_occurrences SET removed_at=clock_timestamp() WHERE id=oid;UPDATE app.activity_assignments SET version=version+1 WHERE occurrence_id=oid;END LOOP;
UPDATE app.exam_supervisor_assignments SET active=false,version=version+1 WHERE active AND(id=rid AND k='supervisor' OR exam_room_id IN(SELECT r.id FROM app.exam_rooms r JOIN app.exam_sessions s ON s.id=r.session_id WHERE(k='room' AND r.id=rid) OR(k='session' AND s.id=rid) OR(k='period' AND s.period_id=rid)));
UPDATE app.exam_committee_assignments SET active=false,version=version+1 WHERE active AND((k='committee' AND id=rid) OR(k='period' AND period_id=rid));
UPDATE app.exam_rooms SET active=false,version=version+1 WHERE active AND((k='room' AND id=rid) OR(k='session' AND session_id=rid) OR(k='period' AND session_id IN(SELECT id FROM app.exam_sessions WHERE period_id=rid)));
UPDATE app.exam_sessions SET active=false,version=version+1 WHERE active AND((k='session' AND id=rid) OR(k='period' AND period_id=rid));UPDATE app.exam_periods SET active=false,version=version+1 WHERE k='period' AND id=rid;
UPDATE ops.module_previews SET consumed_at=clock_timestamp() WHERE id=v.id;UPDATE app.calendar_state SET revision=revision+1 WHERE singleton;PERFORM app.activity_audit('exam-delete',rid,v.request->>'reason',v.request,jsonb_build_object('archived',true));RETURN jsonb_build_object('deleted',true);END $$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app,finance FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.exam_save(text,jsonb),app.exam_delete(text,jsonb) TO sim_guru_business;
RESET ROLE;
